clear
addpath('utils/')


% initialize MSEA model, .fixed and .initial
configFile = "config.json";
params = initialize_msea_model(configFile);

% extract x0
x0 = params.initial.q_0(1);

% set generalized coordinate with added x0
q = [0 0.05 0 0 0 0]';
q(1) = q(1) + x0;

q_delta = [0.001 -0.002 0.003 0.01 -0.01 0.01]'; 
q = q + q_delta;

% use optimization to compute results
[params, errorFlag] = solve_msea_state(q, params);

errorFlag %[output:7c1da0c7]
params.q %[output:739724a8]
params.W_out %[output:07b2efe8]
params.e %[output:17730736]

visualize_double_MSEA(params) %[output:1d1c4b78]

